module TopModule (
    input  logic clk,
    input  logic d,
    output logic q
);

    logic qp, qn;

    always_ff @(posedge clk) begin
        qp <= d;
    end

    always_ff @(negedge clk) begin
        qn <= d;
    end

    assign q = clk ? qp : qn;

endmodule

