module tb_TopModule;
    logic clk;
    logic d;
    logic q;

    TopModule uut (
        .clk(clk),
        .d(d),
        .q(q)
    );

    // Clock generation: 10 time units period (5 high, 5 low)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        d = 0;
        @(posedge clk);
        #1;
        // Test sequence
        // At t=5 (posedge clk), d=0 -> q should be 0
        $display("Time %0t: clk=%b d=%b q=%b (expected 0)", $time, clk, d, q);
        assert(q == 0) else $fatal(1, "Fail at init posedge");

        // Change d while clk is high
        #2 d = 1;
        #3; // now at t=10 (negedge clk)
        // At negedge clk (t=10), q should sample d=1
        #1;
        $display("Time %0t: clk=%b d=%b q=%b (expected 1)", $time, clk, d, q);
        assert(q == 1) else $fatal(1, "Fail at negedge");

        // Change d while clk is low
        #2 d = 0;
        #2; // now at t=15 (posedge clk)
        #1;
        $display("Time %0t: clk=%b d=%b q=%b (expected 0)", $time, clk, d, q);
        assert(q == 0) else $fatal(1, "Fail at posedge");

        // Another edge test
        #3 d = 1; // at t=18, clk is high
        #2; // t=20, negedge clk
        #1;
        $display("Time %0t: clk=%b d=%b q=%b (expected 1)", $time, clk, d, q);
        assert(q == 1) else $fatal(1, "Fail at negedge 2");

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
